sys_script_include.script:
var AttendeeUtils = Class.create();
AttendeeUtils.prototype = {
    initialize: function() {
    },



    isAttendeeRegistered: function(attendeeId) {
        var gr = new GlideRecord('Attendee');
        return gr.get(attendeeId); 
    },


    getAttendeeDetails: function(attendeeId) {
        var result = {};
        var gr = new GlideRecord('Attendee'); 
        if (gr.get(attendeeId)) {
            result.name = gr.getDisplayValue('u_first_name');
            result.email = gr.getValue('u_email');
            result.phone = gr.getValue('u_contact_number');

        }
        return result;
    },


    getAttendeesByEvent: function(eventId) {
        var attendees = [];
        var gr = new GlideRecord('Attendee'); 
        gr.addQuery('u_event_id', eventId);
        gr.query();
        while (gr.next()) {
            attendees.push(gr.getDisplayValue('u_first_name')); 
        }
        return attendees;
    },



    type: 'AttendeeUtils'
};
